CALL = "Llame o envíe un texto al (540) 431-9629."
def cmeta(c, towns):
    return f"Deshollinador y servicios de chimenea en el Condado de {c}, VA, incluidos {towns}. Certificados por la CSIA, empresa familiar y asegurada. {CALL}"
